var eager = &Service{}
func Eager() *Service { return eager }
// 懒汉式：需要 import "sync"
var once sync.Once
var lazy *Service
func Lazy() *Service {
    once.Do(func() { lazy = &Service{} })
    return lazy
}

type Client struct{}
var once sync.Once
var a *Client
func ByOnce() *Client {
    once.Do(func() { a = &Client{} })
    return a
}
var mu sync.Mutex
var b *Client
func ByMutex() *Client {
    mu.Lock()
    defer mu.Unlock()
    if b == nil { b = &Client{} }
    return b
}

