func Logging(next http.Handler) http.Handler {
    return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
        start := time.Now()
        defer func() {
            log.Printf("%s %s took %s", r.Method, r.URL.Path,
                time.Since(start))
        }()
        next.ServeHTTP(w, r)
    })
}

type Node struct { Val int; Next *Node }
func PushFront(head *Node, v int) *Node {
    return &Node{Val: v, Next: head}
}
func DeleteFirst(head *Node, v int) *Node {
    dummy := &Node{Next: head}
    for p := dummy; p.Next != nil; p = p.Next {
        if p.Next.Val == v {
            p.Next = p.Next.Next
            break
        }
    }
    return dummy.Next
}

func Reverse1(s string) string {
    a := []rune(s)
    for i, j := 0, len(a)-1; i < j; i, j = i+1, j-1 {
        a[i], a[j] = a[j], a[i]
    }
    return string(a)
}
func Reverse2(s string) string {
    a := []rune(s)
    b := make([]rune, 0, len(a))
    for i := len(a)-1; i >= 0; i-- { b = append(b, a[i]) }
    return string(b)
}

type MinStack struct { data, mins []int }
func (s *MinStack) Push(x int) {
    m := x
    if n := len(s.mins); n > 0 && s.mins[n-1] < m {
        m = s.mins[n-1]
    }
    s.data = append(s.data, x)
    s.mins = append(s.mins, m)
}
func (s *MinStack) Pop() (int, bool) {
    n := len(s.data)
    if n == 0 { return 0, false }
    x := s.data[n-1]
    s.data, s.mins = s.data[:n-1], s.mins[:n-1]
    return x, true
}
func (s *MinStack) Min() (int, bool) {
    if len(s.mins) == 0 { return 0, false }
    return s.mins[len(s.mins)-1], true
}

// 切片末尾为栈顶，返回新栈，原切片不修改。
func ReverseStack(s []int) []int {
    out := make([]int, 0, len(s))
    for i := len(s)-1; i >= 0; i-- { out = append(out, s[i]) }
    return out
}

type Ring struct { a []int; head, size int }
func NewRing(capacity int) *Ring {
    if capacity < 0 { capacity = 0 }
    return &Ring{a: make([]int, capacity)}
}
func (q *Ring) Push(x int) bool {
    if q.size == len(q.a) { return false }
    q.a[(q.head+q.size)%len(q.a)] = x
    q.size++
    return true
}
func (q *Ring) Pop() (int, bool) {
    if q.size == 0 { return 0, false }
    x := q.a[q.head]
    q.head = (q.head+1)%len(q.a)
    q.size--
    return x, true
}
type QNode struct { v int; next *QNode }
type LinkedQueue struct { head, tail *QNode }
func (q *LinkedQueue) Push(x int) {
    n := &QNode{v: x}
    if q.tail == nil { q.head = n } else { q.tail.next = n }
    q.tail = n
}
func (q *LinkedQueue) Pop() (int, bool) {
    if q.head == nil { return 0, false }
    x := q.head.v
    q.head = q.head.next
    if q.head == nil { q.tail = nil }
    return x, true
}

