type Tree struct { Val int; Left, Right *Tree }
func Inorder(root *Tree) []int {
    out := []int{}
    var walk func(*Tree)
    walk = func(n *Tree) {
        if n == nil { return }
        walk(n.Left)
        out = append(out, n.Val)
        walk(n.Right)
    }
    walk(root)
    return out
}

func Same(a, b *Tree) bool {
    if a == nil || b == nil { return a == b }
    return a.Val == b.Val && Same(a.Left, b.Left) && Same(a.Right, b.Right)
}

func MaxSubtree(root *Tree) (best int64, ok bool) {
    var sum func(*Tree) int64
    sum = func(n *Tree) int64 {
        if n == nil { return 0 }
        v := int64(n.Val) + sum(n.Left) + sum(n.Right)
        if !ok || v > best { best, ok = v, true }
        return v
    }
    sum(root)
    return
}

func Bubble(a []int) {
    for end := len(a)-1; end > 0; end-- {
        changed := false
        for j := 0; j < end; j++ {
            if a[j] > a[j+1] {
                a[j], a[j+1] = a[j+1], a[j]
                changed = true
            }
        }
        if !changed { return }
    }
}

func Selection(a []int) {
    for i := 0; i < len(a)-1; i++ {
        m := i
        for j := i+1; j < len(a); j++ {
            if a[j] < a[m] { m = j }
        }
        a[i], a[m] = a[m], a[i]
    }
}

func Insertion(a []int) {
    for i := 1; i < len(a); i++ {
        x, j := a[i], i-1
        for j >= 0 && a[j] > x {
            a[j+1] = a[j]
            j--
        }
        a[j+1] = x
    }
}

func Quick(a []int) {
    if len(a) < 2 { return }
    pivot := a[len(a)/2]
    lt, i, gt := 0, 0, len(a)-1
    for i <= gt {
        if a[i] < pivot {
            a[lt], a[i] = a[i], a[lt]
            lt++; i++
        } else if a[i] > pivot {
            a[i], a[gt] = a[gt], a[i]
            gt--
        } else { i++ }
    }
    Quick(a[:lt])
    Quick(a[gt+1:])
}

func Binary(a []int, x int) int {
    l, r := 0, len(a)-1
    for l <= r {
        m := l+(r-l)/2
        if a[m] == x { return m }
        if a[m] < x { l = m+1 } else { r = m-1 }
    }
    return -1
}
func BinaryRec(a []int, x int) int {
    var find func(int, int) int
    find = func(l, r int) int {
        if l > r { return -1 }
        m := l+(r-l)/2
        if a[m] == x { return m }
        if a[m] < x { return find(m+1, r) }
        return find(l, m-1)
    }
    return find(0, len(a)-1)
}

type entry struct { key, value int }
type LRU struct {
    cap int
    q *list.List
    m map[int]*list.Element
}
func NewLRU(capacity int) *LRU {
    if capacity < 0 { capacity = 0 }
    return &LRU{capacity, list.New(), make(map[int]*list.Element)}
}
func (c *LRU) Get(k int) (int, bool) {
    e, ok := c.m[k]
    if !ok { return 0, false }
    c.q.MoveToFront(e)
    return e.Value.(entry).value, true
}
func (c *LRU) Put(k, v int) {
    if c.cap == 0 { return }
    if e, ok := c.m[k]; ok {
        e.Value = entry{k, v}
        c.q.MoveToFront(e)
        return
    }
    c.m[k] = c.q.PushFront(entry{k, v})
    if c.q.Len() > c.cap {
        e := c.q.Back()
        delete(c.m, e.Value.(entry).key)
        c.q.Remove(e)
    }
}
